            GameLocalizationCatalog catalog=AssetDatabase.LoadAssetAtPath<GameLocalizationCatalog>(V3UiLocalizationCatalogBuilder.CatalogPath)??throw new InvalidOperationException("Localization catalog missing.");var tables=new List<GameLocaleTable>();
