        private static void BuildGuide()
        {
            var guide=AssetDatabase.LoadAssetAtPath<MissionFieldGuideConfig>(GuidePath);if(guide==null){guide=ScriptableObject.CreateInstance<MissionFieldGuideConfig>();AssetDatabase.CreateAsset(guide,GuidePath);}var basis=AssetDatabase.LoadAssetAtPath<MissionFieldGuideConfig>(M03RadarWarningGuideBuilder.Path);var classes=basis.Classes.ToArray();for(int i=0;i<classes.Length;i++)if(classes[i].Availability!=MissionGuideAvailability.Unavailable)classes[i].Availability=MissionGuideAvailability.Reference;
            guide.Configure(Enumerable.Range(1,6).Select(i=>new MissionGuideTopic{TitleKey=$"mission.route_reopened.guide.{i}.title",BodyKey=$"mission.route_reopened.guide.{i}.body",ExampleKey="mission.route_reopened.guide.example",MistakeKey="mission.route_reopened.guide.mistake",DiagramKey="mission.route_reopened.guide.diagram"}).ToArray(),classes);EditorUtility.SetDirty(guide);
            GameObject root=PrefabUtility.LoadPrefabContents(M03RadarWarningUiBuilder.GuidePath);try{var data=new SerializedObject(root.GetComponentInChildren<MissionFieldGuideView>(true));data.FindProperty("routeReopenedGuide").objectReferenceValue=guide;data.ApplyModifiedPropertiesWithoutUndo();MissionUiSerializedBindingsAuthoring.Apply(root);PrefabUtility.SaveAsPrefabAsset(root,M03RadarWarningUiBuilder.GuidePath);}finally{PrefabUtility.UnloadPrefabContents(root);}
        }
        private static void BindArt()
        {
            Texture art=CH02M05RouteReopenedMediaImporter.Preview()??throw new InvalidOperationException("Route Reopened art missing.");foreach(string path in new[]{"Assets/Game/Prefabs/UI/Shell/Content/SCN05_CampaignOperationsContent.prefab","Assets/Game/Prefabs/UI/Shell/Content/SCN06_MissionBriefingContent.prefab"}){GameObject root=PrefabUtility.LoadPrefabContents(path);try{var campaign=root.GetComponentInChildren<CampaignOperationsScreenView>(true);UnityEngine.Object view=campaign!=null?(UnityEngine.Object)campaign:root.GetComponentInChildren<MissionBriefingScreenView>(true);var data=new SerializedObject(view);data.FindProperty(campaign!=null?"routeReopenedMissionPreview":"routeReopenedMissionArt").objectReferenceValue=art;data.ApplyModifiedPropertiesWithoutUndo();PrefabUtility.SaveAsPrefabAsset(root,path);}finally{PrefabUtility.UnloadPrefabContents(root);}}
        }
